round:#f8fafc;font-size:12px}td{color:#334155}.description{max-width:320px;color:#64748b}code{display:block;max-width:210px;overflow:hidden;color:#94a3b8;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.unit-tag{padding:3px 8px;border-radius:5px;color:#0369a1;background:#e0f2fe;font-size:11px}.actions{display:flex;gap:6px}.actions button,.model-card footer button{padding:5px 8px;border:0;border-radius:5px;color:#2563eb;background:#eff6ff;cursor:pointer}.danger{color:#dc2626!important;background:#fef2f2!important}.empty{padding:30px;text-align:center;color:#94a3b8;font-size:12px}.empty.full{grid-column:1/-1}.pagination{display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:16px 24px;color:#94a3b8;font-size:11px}.pagination button{height:30px;padding:0 10px;border:1px solid #e2e8f0;border-radius:6px;background:#fff;color:#475569;cursor:pointer}.pagination button:disabled{opacity:.4}.model-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:14px;padding:0 24px}.model-card{padding:16px;border:1px solid #e2e8f0;border-radius:11px;background:#fff}.model-card header{display:flex;justify-content:space-between}.model-card h3{margin:6px 0 0;font-size:17px}.type-label{color:#2563eb;font-size:10px}.count{color:#94a3b8;font-size:11px}.remark{height:34px;color:#64748b;font-size:12px}.bound-points{min-height:58px;display:flex;align-content:flex-start;flex-wrap:wrap;gap:5px;padding:9px;border-radius:7px;background:#f8fafc}.bound-points span{padding:4px 7px;border:1px solid #e2e8f0;border-radius:5px;background:#fff;font-size:11px}.bound-points small{margin-left:3px;color:#94a3b8}.bound-points em{color:#94a3b8;font-size:11px;font-style:normal}.model-card footer{display:flex;align-items:center;justify-content:space-between;margin-top:12px}.model-card footer div{display:flex;gap:5px}.alert{margin:0 24px 12px;padding:9px 12px;border-radius:7px;color:#b91c1c;background:#fef2f2;font-size:12px}.overlay{position:fixed;inset:0;z-index:1000;display:flex;align-items:center;justify-content:center;background:rgba(15,23,42,.46)}.modal{width:570px;max-width:92vw;max-height:90vh;display:flex;flex-direction:column;border-radius:14px;background:#fff;box-shadow:0 24px 70px rgba(15,23,42,.24);overflow:hidden}.modal.model-modal{width:720px}.modal>header{padding:20px 22px 0}.modal>header h3{margin:0 0 4px;font-size:18px}.modal>header p{margin:0;color:#94a3b8;font-size:11px}.modal-body{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:20px 22px;overflow-y:auto}.modal-body label{display:flex;flex-direction:column;gap:6px;color:#475569;font-size:12px;font-weight:600}.modal-body label span{color:#dc2626}.modal-body input,.modal-body textarea{width:100%;padding:9px 11px;border:1px solid #cbd5e1;border-radius:7px;color:#172033;background:#fff;outline:none}.modal-body input:disabled{color:#64748b;background:#f1f5f9}.modal-body textarea{resize:vertical}.modal-body label>small{align-self:flex-end;color:#94a3b8}.wide{grid-column:1/-1}.modal .alert{margin:0}.modal>footer{display:flex;justify-content:flex-end;gap:8px;padding:0 22px 20px}.point-selector{border:1px solid #e2e8f0;border-radius:9px;overflow:hidden}.selector-title{display:flex;justify-content:space-between;padding:10px 12px;border-bottom:1px solid #e2e8f0;background:#f8fafc}.selector-title span{color:#2563eb;font-size:11px}.point-options{max-height:270px;display:grid;grid-template-columns:1fr 1fr;gap:7px;padding:10px;overflow-y:auto}.point-options label{display:flex;flex-direction:row;align-items:center;padding:9px;border:1px solid #e2e8f0;border-radius:7px;cursor:pointer}.point-options label.selected{border-color:#93c5fd;background:#eff6ff}.point-options label.locked{cursor:not-allowed}.point-options input{width:auto}.point-options label>span{min-width:0;display:flex;flex-direction:column;color:#334155}.point-options b{font-size:12px}.point-options small{overflow:hidden;color:#94a3b8;font-size:10px;text-overflow:ellipsis;white-space:nowrap}@media(max-width:700px){.page-content{padding:20px}.page-title{align-items:flex-start;flex-direction:column;gap:12px}.relation{display:none}.module-tabs button{min-width:0;flex:1}.modal-body,.point-options{grid-template-columns:1fr}.wide{grid-column:auto}.model-grid{grid-template-columns:1fr}}
