.page-content{padding:20px 28px;overflow:hidden}.workspace{height:calc(100vh - 40px);min-height:0;display:flex;flex-direction:column}.sibling-tabs{margin-bottom:16px;flex-shrink:0}.sibling-tab{display:flex;align-items:center;gap:8px;padding:8px 18px;font-size:14px;font-weight:500;transition:background .2s ease,color .2s ease}.sibling-tab:hover{color:#334155;background:#f1f5f9}.page-title{flex-shrink:0;margin-bottom:14px}.page-title h1{font-size:22px;color:#0f172a}.main-card{flex:1;min-height:0;display:flex;flex-direction:column;border:0;border-radius:16px;box-shadow:0 4px 16px rgba(15,23,42,.05)}.module-tabs{flex-shrink:0;padding:5px 8px}.module-tabs button{padding:9px 16px}.module-tabs button:hover:not(.active){color:#334155;background:#eef2f7}.toolbar{flex-shrink:0;padding:16px 24px;border-bottom:1px solid #f1f5f9}.btn{font-size:13px;transition:background .2s ease,opacity .2s ease}.btn.primary{background:#3b82f6}.btn.primary:hover:not(:disabled){background:#2563eb}.btn.muted:hover:not(:disabled){background:#e2e8f0}.table-wrap{flex:1;min-height:0;overflow:auto}tbody tr{transition:background .15s ease}tbody tr:hover{background:#f8fafc}.actions button,.model-card footer button{transition:background .15s ease,color .15s ease}.actions button:hover,.model-card footer button:hover{color:#1d4ed8;background:#dbeafe}.pagination{flex-shrink:0;margin-top:auto;border-top:1px solid #f1f5f9}.pagination button:hover:not(:disabled){border-color:#94a3b8;background:#f8fafc}.model-grid{flex:1;min-height:0;align-content:start;overflow-y:auto;padding-top:2px}.model-card{box-shadow:0 2px 7px rgba(15,23,42,.035);transition:border-color .2s ease,box-shadow .2s ease}.model-card:hover{border-color:#cbd5e1;box-shadow:0 5px 14px rgba(15,23,42,.07)}.modal-body input:focus,.modal-body textarea:focus{border-color:#3b82f6;box-shadow:0 0 0 3px rgba(59,130,246,.12)}
@media(max-width:700px){.page-content{padding:20px;overflow:auto}.workspace{height:auto;min-height:calc(100vh - 40px)}.main-card{min-height:620px}}
